export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

/**
 * Per-category pricing and validation rules. Driving the category logic from a
 * small config table removes the near-identical boilerplate that was repeated
 * three times while leaving the resulting behavior unchanged.
 */
interface BookingCategory {
  name: string;
  nightsMax: number;
  /** Optional special minimum stay (villa enforces 3 nights with its own message). */
  minStay?: number;
  guestsMax: number;
  /** Price per night outside high season. */
  baseNight: number;
  /** Extra charged per night during high season. */
  highBonus: number;
  /** One-time flat fee added last (villa cleaning). */
  cleaningFee: number;
  /** One-time surcharge applied once guests exceed `extraGuestFrom`. */
  extraGuestFee: number;
  /** Guests strictly above this number trigger the surcharge. */
  extraGuestFrom: number;
}

const CATEGORIES: Record<string, BookingCategory> = {
  standard: {

    name: "standard",
    nightsMax: 14,
    guestsMax: 2,
    baseNight: 80,
    highBonus: 30,
    cleaningFee: 0,
    extraGuestFee: 0,
    extraGuestFrom: 2,
  },
  suite: {
    name: "suite",
    nightsMax: 21,
    guestsMax: 4,
    baseNight: 150,
    highBonus: 60,
    cleaningFee: 0,
    extraGuestFee: 25,
    extraGuestFrom: 2,
  },
  villa: {
    name: "villa",
    nightsMax: 28,
    minStay: 3,
    guestsMax: 8,
    baseNight: 300,
    highBonus: 120,
    cleaningFee: 500,
    extraGuestFee: 0,
    extraGuestFrom: 8,
  },
};

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;

  const loyaltyYears = req.l

oyaltyYears;
  if (
    typeof loyaltyYears !== "number" ||
    !Number.isInteger(loyaltyYears) ||
    (loyaltyYears as number) < 0
  ) {
    return { ok: false, error: "bad loyalty" };
