export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

/**
 * Per-category pricing and validation rules. Driving the category logic from a
 * small config table removes the near-identical boilerplate that was repeated
 * three times while leaving the resulting behavior unchanged.
 */
interface BookingCategory {
  name: string;
  nightsMax: number;
  /** Optional special minimum stay (villa enforces 3 nights with its own message). */
  minStay?: number;
  guestsMax: number;
  /** Price per night outside high season. */
  baseNight: number;
  /** Extra charged per night during high season. */
  highBonus: number;
  /** One-time flat fee added last (villa cleaning). */
  cleaningFee: number;
  /** One-time surcharge applied once guests exceed `extraGuestFrom`. */
  extraGuestFee: number;
  /** Guests strictly above this number trigger the surcharge. */
  extraGuestFrom: number;
}

const CATEGORIES: Record<string, BookingCategory> = {
  standard: {
    name: "standard",
    nightsMax: 14,
    guestsMax: 2,
    baseNight: 80,
    highBonus: 30,
    cleaningFee: 0,
    extraGuestFee: 0,
    extraGuestFrom: 2,
  },
  suite: {
    name: "suite",
    nightsMax: 21,
    guestsMax: 4,
    baseNight: 150,
    highBonus: 60,
    cleaningFee: 0,
    extraGuestFee: 25,
    extraGuestFrom: 2,
  },
  villa: {
    name: "villa",
    nightsMax: 28,
    minStay: 3,
    guestsMax: 8,
    baseNight: 300,
    highBonus: 120,
    cleaningFee: 500,
    extraGuestFee: 0,
    extraGuestFrom: 8,
  },
};

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;

  const loyaltyYears = req.loyaltyYears;
  if (
    typeof loyaltyYears !== "number" ||
    !Number.isInteger(loyaltyYears) ||
    (loyaltyYears as number) < 0
  ) {
    return { ok: false, error: "bad loyalty" };
  }

  const category = CATEGORIES[String((req.category as string) ?? "")];
  if (!category) {
    return { ok: false, error: "unknown category" };
  }

  const nights = req.nights;
  if (
    typeof nights !== "number" ||
    !Number.isInteger(nights) ||
    (nights as number) < 1 ||
    (nights as number) > category.nightsMax
  ) {
    return { ok: false, error: "bad nights" };
  }
  if (category.minStay !== undefined && (nights as number) < category.minStay) {
    return { ok: false, error: "villa minimum stay" };
  }

  const guests = req.guests;
  if (
    typeof guests !== "number" ||
    !Number.isInteger(guests) ||
    (guests as number) < 1 ||
    (guests as number) > category.guestsMax
  ) {
    return { ok: false, error: "bad guests" };
  }

  if (req.season !== "low" && req.season !== "high") {
    return { ok: false, error: "bad season" };
  }

  // All three categories award the 10% discount (and flexible policy) for the
  // same condition: a VIP coupon or at least 3 years of loyalty.
  const privileged = req.coupon === "VIP" || (loyaltyYears as number) >= 3;

  let total = category.baseNight * (nights as number);
  if (req.season === "high") {
    total += category.highBonus * (nights as number);
  }
  if (privileged) {
    total -= Math.floor(total / 10);
  }
  if ((guests as number) > category.extraGuestFrom) {
    total += category.extraGuestFee;
  }
  total += category.cleaningFee;

  const policy = privileged ? "flex" : "strict";
  const line =
    category.name + ":" + String(nights) + "n:" + String(total) + ":" + policy;
  return { ok: true, total, policy, line };
}

export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

/**
 * Per-category pricing and validation rules. Driving the category logic from a
 * small config table removes the near-identical boilerplate that was repeated
 * three times while leaving the resulting behavior unchanged.
 */
interface BookingCategory {
  name: string;
  nightsMax: number;
  /** Optional special minimum stay (villa enforces 3 nights with its own message). */
  minStay?: number;
  guestsMax: number;
  /** Price per night outside high season. */
  baseNight: number;
  /** Extra charged per night during high season. */
  highBonus: number;
  /** One-time flat fee added last (villa cleaning). */
  cleaningFee: number;
  /** One-time surcharge applied once guests exceed `extraGuestFrom`. */
  extraGuestFee: number;
  /** Guests strictly above this number trigger the surcharge. */
  extraGuestFrom: number;
}

const CATEGORIES: Record<string, BookingCategory> = {
  standard: {
    name: "standard",
    nightsMax: 14,
    guestsMax: 2,
    baseNight: 80,
    highBonus: 30,
